import csv
import io


def inspect_csv(csv_text):
    if not csv_text or not csv_text.strip():
        return None
    reader = csv.reader(io.StringIO(csv_text))
    rows = list(reader)
    if not rows:
        return None
    columns = rows[0]
    row_count = len(rows) - 1
    return {'columns': columns, 'row_count': row_count}

