def standardize(values):
    if not values:
        return None
    count = len(values)
    total = 0.0
    for value in values:
        total += value
    mean = total / count
    squared_difference = 0.0
    for value in values:
        difference = value - mean
        squared_difference += difference * difference
    variance = squared_difference / count
    std_dev = variance ** 0.5
    if std_dev == 0:
        return None
    return [
        round((value - mean) / std_dev, 4)
        for value in values
    ]

def split_indices(n, train_ratio, validation_ratio, test_ratio, seed=0):
    total = train_ratio + validation_ratio + test_ratio
    if abs(total - 1.0) > 1e-9:
        raise ValueError('ratios must sum to 1')
    if train_ratio < 0 or validation_ratio < 0 or test_ratio < 0:
        raise ValueError('ratios must be non-negative')
    indices = list(range(n))
    # Deterministic Fisher-Yates shuffle seeded by seed.
    state = seed
    for i in range(n - 1, 0, -1):
        state = (state * 1103515245 + 12345) % (2 ** 31)
        j = state % (i + 1)
        indices[i], indices[j] = indices[j], indices[i]
    train_end = int(round(train_ratio * n))
    validation_end = train_end + int(round(validation_ratio * n))
    return {
        'train': indices[:train_end],
        'validation': indices[train_end:validation_end],
        'test': indices[validation_end:],
    }

