def forward_pass(inputs, weights, bias=0.0):
    if not inputs or not weights or len(inputs) != len(weights):
        return None
    z = bias
    for x, w in zip(inputs, weights):
        z += x * w
    return round(1 / (1 + 2.718281828459045 ** (-z)), 4)

