def numerical_summary(values):
    if not values:
        return None
    minimum = values[0]
    maximum = values[0]
    for value in values:
        if value < minimum:
            minimum = value
        if value > maximum:
            maximum = value
    return {'min': minimum, 'max': maximum, 'count': len(values)}

