def rebuild_and_search_index(records, query_vector, target_dim=1536, top_k=3):
    if len(query_vector) != target_dim:
        return []
    q_norm = sum(x * x for x in query_vector) ** 0.5
    if q_norm == 0:
        return []
    norm_q = [x / q_norm for x in query_vector]

    scored = []
    for rec in records:
        v = rec.get("vector", [])
        if len(v) != target_dim:
            continue
        v_norm = sum(x * x for x in v) ** 0.5
        if v_norm == 0:
            continue
        norm_v = [x / v_norm for x in v]
        similarity = sum(a * b for a, b in zip(norm_q, norm_v))
        scored.append((rec["id"], round(similarity, 4)))

    scored.sort(key=lambda item: (-item[1], item[0]))
    return scored[:top_k]

def safe_chunk_document(text, chunk_size=200, chunk_overlap=40):
    if chunk_size <= 0:
        raise ValueError("chunk_size must be positive")
    if chunk_overlap < 0 or chunk_overlap >= chunk_size:
        raise ValueError("chunk_overlap must be less than chunk_size and non-negative")
    cleaned = text.strip()
    if not cleaned:
        return []

    chunks = []
    step = chunk_size - chunk_overlap
    start = 0
    index = 0
    n = len(cleaned)

    while start < n:
        target_end = min(start + chunk_size, n)
        actual_end = target_end
        if target_end < n and not cleaned[target_end].isspace():
            last_space = cleaned.rfind(" ", start, target_end)
            if last_space > start:
                actual_end = last_space
        chunk_str = cleaned[start:actual_end].strip()
        if chunk_str:
            chunks.append({
                "index": index,
                "text": chunk_str,
                "start": start,
                "end": actual_end,
            })
            index += 1
        if actual_end >= n:
            break
        next_start = start + step
        if next_start <= start:
            next_start = start + 1
        if next_start >= n:
            break
        start = next_start

    return chunks

