def resolve_service_endpoint(service_name, target_service, port, env_config, network_mode="bridge"):
    key = f"{target_service.upper()}_HOST"
    host = env_config.get(key, target_service)
    if network_mode == "bridge":
        if host in ("localhost", "127.0.0.1", "::1"):
            host = target_service
    elif network_mode == "host":
        if host == target_service:
            host = "localhost"
    return f"{host}:{port}"

def audit_compose_config(services):
    issues = []
    for s_name, s_def in services.items():
        env = s_def.get("environment", {})
        for env_k, env_v in env.items():
            val = str(env_v)
            if ("localhost" in val or "127.0.0.1" in val) and any(peer in env_k.lower() for peer in services if peer != s_name):
                issues.append(f"{s_name}: environment {env_k} references loopback ({val}) instead of container service name")
        bind = str(env.get("HOST", ""))
        if bind in ("127.0.0.1", "localhost"):
            issues.append(f"{s_name}: server process bound to {bind}; must bind to 0.0.0.0 to accept bridge traffic")
    return {"valid": len(issues) == 0, "issues": issues}
